function getMinimumDifference(root: TreeNode | null): number {
  let best = Infinity;
  // Значение предыдущего узла в порядке in-order (то есть по возрастанию)
  let prev: number | null = null;

  const inorder = (node: TreeNode | null): void => {
    if (node === null) {
      return;
    }

    // Сначала все меньшие значения
    inorder(node.left);

    // node.val и prev — соседи в отсортированном порядке
    if (prev !== null) {
      best = Math.min(best, node.val - prev);
    }
    prev = node.val;

    // Затем все большие значения
    inorder(node.right);
  };

  inorder(root);
  return best;
}

// Время: O(n) — один обход дерева
// Память: O(h) — стек рекурсии
